From c84ecb784df26b0a83ca37aad55f95436ba1af3c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:40:12 +0100
Subject: [PATCH] wallpapers/image: allow a different wallpaper for each
 virtual desktop

Every virtual desktop always showed the same image. A new option
remembers the image of each desktop and shows it again when that desktop
becomes current, so choosing an image only changes that desktop.

BUG: 341143
---
 .../imagepackage/contents/config/main.xml     | 12 ++++
 .../image/imagepackage/contents/ui/config.qml | 20 ++++++
 .../image/imagepackage/contents/ui/main.qml   | 71 +++++++++++++++++++
 3 files changed, 103 insertions(+)

diff --git a/wallpapers/image/imagepackage/contents/config/main.xml b/wallpapers/image/imagepackage/contents/config/main.xml
index 1c47869b78..e6cc3d3551 100644
--- a/wallpapers/image/imagepackage/contents/config/main.xml
+++ b/wallpapers/image/imagepackage/contents/config/main.xml
@@ -79,5 +79,17 @@
       <label>Force animated images to play</label>
       <default>false</default>
     </entry>
+    <entry name="PerVirtualDesktop" type="bool">
+      <label>Use a different wallpaper image for each virtual desktop</label>
+      <default>false</default>
+    </entry>
+    <entry name="VirtualDesktopImages" type="StringList">
+      <label>Wallpaper image of each virtual desktop</label>
+      <tooltip>
+        Entries in the form "desktop id=image". Image always holds the image of the
+        current virtual desktop, and is set from this list when the desktop changes.
+      </tooltip>
+      <default></default>
+    </entry>
   </group>
 </kcfg>
diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..e78cb89eee 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -16,6 +16,7 @@ import org.kde.newstuff as NewStuff
 import org.kde.kcmutils as KCM
 import org.kde.kirigami as Kirigami
 import org.kde.config as KConfig
+import org.kde.taskmanager as TaskManager

 /**
  * For proper alignment, an ancestor **MUST** have id "appearanceRoot" and property "parentLayout"
@@ -50,6 +51,8 @@ ColumnLayout {
     property int cfg_DynamicModeDefault: 0
     property bool cfg_ForceImageAnimation: false
     property bool cfg_ForceImageAnimationDefault: false
+    property alias cfg_PerVirtualDesktop: perVirtualDesktopCheckBox.checked
+    property bool cfg_PerVirtualDesktopDefault: false

     signal configurationChanged()
     /**
@@ -267,6 +270,23 @@ ColumnLayout {
                 }
             }
         }
+
+        QtControls2.CheckBox {
+            id: perVirtualDesktopCheckBox
+            // Not offered for the lock screen, which has no virtual desktops
+            visible: root.configDialog.currentWallpaper === "org.kde.image"
+                && root.configDialog.shellConfiguration === undefined
+                && (virtualDesktopInfo.numberOfDesktops > 1 || checked)
+            text: i18ndc("plasma_wallpaper_org.kde.image", "@option:check", "Use a different wallpaper for each virtual desktop")
+
+            KCM.SettingHighlighter {
+                highlight: root.cfg_PerVirtualDesktop !== root.cfg_PerVirtualDesktopDefault
+            }
+
+            TaskManager.VirtualDesktopInfo {
+                id: virtualDesktopInfo
+            }
+        }
     }

     DropArea {
diff --git a/wallpapers/image/imagepackage/contents/ui/main.qml b/wallpapers/image/imagepackage/contents/ui/main.qml
index 14aac831f8..bd83bfcf37 100644
--- a/wallpapers/image/imagepackage/contents/ui/main.qml
+++ b/wallpapers/image/imagepackage/contents/ui/main.qml
@@ -10,6 +10,7 @@ import QtQuick
 import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.wallpapers.image as Wallpaper
 import org.kde.plasma.plasmoid
+import org.kde.taskmanager as TaskManager

 WallpaperItem {
     id: root
@@ -53,6 +54,76 @@ WallpaperItem {
         root.loading = true; // delays ksplash until the wallpaper has been loaded
     }

+    Loader {
+        active: root.pluginName === "org.kde.image" && root.configuration.PerVirtualDesktop
+        onActiveChanged: {
+            if (!active) {
+                root.configuration.VirtualDesktopImages = [];
+                root.configuration.writeConfig();
+            }
+        }
+
+        sourceComponent: QtObject {
+            id: perDesktop
+
+            // Image always holds the current desktop's image, so the config dialog and
+            // anything setting Image from outside apply to the current desktop
+            readonly property string image: root.configuration.Image
+            readonly property string screenName: root.Screen.name
+            property string desktop
+
+            function imageFor(desktop: string): string {
+                const entry = root.configuration.VirtualDesktopImages.find(entry => entry.startsWith(desktop + "="));
+                return entry ? entry.slice(desktop.length + 1) : "";
+            }
+
+            function setImageFor(desktop: string, image: string): bool {
+                if (imageFor(desktop) === image) {
+                    return false;
+                }
+                const images = root.configuration.VirtualDesktopImages.filter(entry => !entry.startsWith(desktop + "="));
+                images.push(desktop + "=" + image);
+                root.configuration.VirtualDesktopImages = images;
+                return true;
+            }
+
+            function updateDesktop(): void {
+                const current = String(virtualDesktopInfo.currentDesktopByScreenName(screenName) ?? "");
+                if (current === desktop) {
+                    return;
+                }
+                let changed = desktop !== "" && setImageFor(desktop, image);
+                desktop = current;
+                if (desktop !== "") {
+                    const desktopImage = imageFor(desktop);
+                    if (desktopImage === "") {
+                        changed = setImageFor(desktop, image) || changed;
+                    } else if (desktopImage !== image) {
+                        root.configuration.Image = desktopImage;
+                        changed = true;
+                    }
+                }
+                if (changed) {
+                    root.configuration.writeConfig();
+                }
+            }
+
+            onScreenNameChanged: updateDesktop()
+            onImageChanged: {
+                if (desktop !== "" && setImageFor(desktop, image)) {
+                    root.configuration.writeConfig();
+                }
+            }
+
+            property TaskManager.VirtualDesktopInfo virtualDesktopInfo: TaskManager.VirtualDesktopInfo {
+                onCurrentDesktopChanged: perDesktop.updateDesktop()
+                onCurrentDesktopForScreenChanged: perDesktop.updateDesktop()
+            }
+
+            Component.onCompleted: updateDesktop()
+        }
+    }
+
     Rectangle {
         anchors.fill: parent
         color: root.configuration.Color
-- 
